    /**
     * Telemetry Run Id
     */
    telemetry_run_id?: string | null;
    /**
     * Installation Id
     */
    installation_id?: number | null;
    /**
     * Branch
     */
    branch?: string | null;
    /**
     * Trigger
     */
    trigger?: string | null;
    /**
     * Score
     */
    score?: number | null;
    /**
     * Grade
     */
    grade?: string | null;
    /**
     * Issues Count
     */
    issues_count?: number | null;
    /**
     * Error
     */
    error?: string | null;
    /**
     * Pr Url
     */
    pr_url?: string | null;
    /**
     * Pr Branch
     */
    pr_branch?: string | null;
    /**
     * Org Name
     */
